def solve_small(n):
    black_squares = []
    for r in range(n):
        for c in range(n):
            if (r + c) % 2 == 0:
                black_squares.append((r, c))

    num_black = len(black_squares)
    trominos = []
    for r in range(n - 1):
        for c in range(n - 1):
            squares = [(r, c), (r+1, c), (r, c+1), (r+1, c+1)]
            for i in range(4):
                t = set([squares[j] for j in range(4) if j != i])
                # Only keep trominos that cover at least one black square
                if any((sq[0] + sq[1]) % 2 == 0 for sq in t):
                    trominos.append(t)

    # We need to select a subset of trominos that are non-overlapping
    # and their union contains all black squares.
    # This is equivalent to:
    # Each black square must be covered by exactly one tromino.

    # Let's use backtracking to find the minimum number of trominos.
    min_k = float('inf')

    def backtrack(b_idx, used_squares, k):
        nonlocal min_k
        if k >= min_k:
            return

        if b_idx == num_black:
            min_k = k
            return

        b_sq = black_squares[b_idx]
        if b_sq in used_squares:
            backtrack(b_idx + 1, used_squares, k)
            return

        # Try all trominos that cover b_sq
        for t in trominos:
            if b_sq in t:
                if all(sq not in used_squares for sq in t):
                    backtrack(b_idx + 1, used_squares | t, k + 1)

    backtrack(0, set(), 0)
    return min_k

for n in range(3, 8, 2):
    print(f"n={n}, min_k={solve_small(n)}")

