def solve_fast(n):
    black_squares = []
    for r in range(n):
        for c in range(n):
            if (r + c) % 2 == 0:
                black_squares.append((r, c))
    num_black = len(black_squares)

    trominos = []
    for r in range(n - 1):
        for c in range(n - 1):
            squares = [(r, c), (r+1, c), (r, c+1), (r+1, c+1)]
            for i in range(4):
                t = tuple(sorted([squares[j] for j in range(4) if j != i]))
                trominos.append(t)

    # We want to find a set of disjoint trominos that cover all black_squares.
    # This is a classic exact cover problem if we consider all squares.
    # But we only care about black squares.
    # Let's use backtracking with pruning.

    import collections

    # Pre-calculate which trominos cover which black square
    black_to_trominos = collections.defaultdict(list)
    for i, t in enumerate(trominos):
        for sq in t:
            if (sq[0] + sq[1]) % 2 == 0:
                black_to_trominos[sq].append(i)

    memo = {}

    def backtrack(b_idx, used_squares):
        if b_idx == num_black:
            return 0

        b_sq = black_squares[b_idx]
        if b_sq in used_squares:
            return backtrack(b_idx + 1, used_squares)

        state = (b_idx, tuple(sorted(list(used_squares))))
        if state in memo: return memo[state]

        res = float('inf')
        for t_idx in black_to_trominos[b_sq]:
            t = trominos[t_idx]
            if all(sq not in used_squares for sq in t):
                new_used = used_squares | set(t)
                val = backtrack(b_idx + 1, new_used)
                if val != float('inf'):
                    res = min(res, 1 + val)

        memo[state] = res
        return res

    # The state should not include all used_squares.
    # Only the squares that could possibly be used by future black squares.
    # A square (r,c) can only affect black squares in its neighborhood.

    def backtrack_optimized(b_idx, used_squares):
        if b_idx == num_black:
            return 0

        b_sq = black_squares[b_idx]
        if b_sq in used_squares:
            return backtrack_optimized(b_idx + 1, used_squares)

        # Pruning: if we can't cover the remaining black squares
        # (not very effective)

        res = float('inf')
        for t_idx in black_to_trominos[b_sq]:
            t = trominos[t_idx]
            if all(sq not in used_squares for sq in t):
                # Only keep used_squares that are "near" the current or future black squares
                # A square (r,c) is "near" if its distance to the current or future black squares is small.
                # For simplicity, let's just keep all used_squares and see.
                new_used = used_squares | set(t)
                val = backtrack_optimized(b_idx + 1, new_used)
                if val != float('inf'):
                    res = min(res, 1 + val)
        return
